function range(start, end, step = 1) {
  if (step === 0) throw new RangeError("step must not be 0");
  return {
    *[Symbol.iterator]() {
      for (let n = start; step > 0 ? n < end : n > end; n += step) yield n;
    },
  };
}

const r = range(0, 10, 4);
console.log([...r], [...r]);
try {
  range(0, 10, 0);
} catch (error) {
  console.log(error.name);
}

