questions.solution:
function* backoff(firstMs, maxMs) {
  let delay = firstMs;
  while (true) {
    yield delay;
    delay = Math.min(delay * 2, maxMs);
  }
}

console.log(backoff(250, 3000).take(6).toArray().join(" "));

