questions.solution:
function* flatten(value) {
  if (Array.isArray(value)) {
    for (const item of value) yield* flatten(item);
  } else {
    yield value;
  }
}

console.log([...flatten(["RICE", ["OIL", ["SALT", "SUGAR"]], [], "TEA"])]);

