const PAGES = {
  start: { items: ["ORD-1", "ORD-2"], nextCursor: "c2" },
  c2: { items: ["ORD-3"], nextCursor: null },
};
let requests = 0;
async function fetchPage(cursor) {
  requests++;
  return PAGES[cursor ?? "start"];
}

async function* paginate(fetchPage) {
  let cursor = null;
  do {
    const page = await fetchPage(cursor);
    yield* page.items;
    cursor = page.nextCursor;
  } while (cursor !== null);
}

async function main() {
  const ids = [];
  for await (const id of paginate(fetchPage)) ids.push(id);
  console.log(ids.join(" "), requests);
}
main();
